  <?php
// 数据库配置（从环境变量读取，兼容 Docker 和本地）
$host = getenv('DB_HOST') ?: 'qgskdt-db-mysql.ns-ya272tf8';
$dbname = getenv('DB_NAME') ?: 'mydb';
$username = getenv('DB_USER') ?: 'root';
$password = getenv('DB_PASSWORD') ?: '9vzn8qlr';

try {
    // 建立数据库连接
    $pdo = new PDO(
        "mysql:host=$host;dbname=$dbname;charset=utf8mb4",
        $username,
        $password,
        [
            PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION,
            PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC
        ]
    );

    // 1. 从v_industry_rank视图获取按顺序排列的行业列表
    $industryStmt = $pdo->query("
        SELECT industry, count_num, rank_num
        FROM v_industry_rank;
    ");
    $industrie = $industryStmt->fetchAll(PDO::FETCH_COLUMN, 0);

    // 2. 查询颜色列表（新增）
    $colourStmt = $pdo->query("
        SELECT colour
        FROM colour;
    ");
    $colours = $colourStmt->fetchAll(PDO::FETCH_COLUMN, 0); // 颜色数组，如：['#ff0000', '#00ff00']
    $colourCount = count($colours); // 颜色数量
    $defaultColour = '#cccccc'; // 颜色数组为空时的默认色

    //11111
    $dayQgskdt = '';
$stmt = $pdo->query("SELECT * FROM day_qgskdt LIMIT 1");
if ($row = $stmt->fetch()) {
    // 假设表中唯一字段名为value，根据实际字段名修改
    $dayQgskdt = current($row);
}

// 获取城市（正序赋值）
$cities = $pdo->query("SELECT citi FROM top3_citi_count_v ORDER BY rank_num LIMIT 3")
              ->fetchAll(PDO::FETCH_COLUMN);
// 用数组解构，不足3个时自动补空
[$city1, $city2, $city3] = array_pad($cities, 3, '');

// 获取行业（倒序赋值，若需要）
$industries = $pdo->query("SELECT industry FROM top3_industry_count_v ORDER BY rank_num LIMIT 3")
                  ->fetchAll(PDO::FETCH_COLUMN);
// 反转数组后解构（如果原数组是[Top3, Top2, Top1]，反转后变为[Top1, Top2, Top3]）
$industries = array_reverse($industries);
[$industrys3, $industrys2, $industrys1] = array_pad($industries, 3, '');

// 4. 获取v_table_stats表的统计数据
$totalRows = 0;
$distinctCitiCount = 0;
$distinctIndustryCount = 0;
$stmt = $pdo->query("SELECT total_rows, distinct_citi_count, distinct_industry_count FROM v_table_stats LIMIT 1");
if ($stats = $stmt->fetch()) {
    $totalRows = $stats['total_rows'] ?? 0;
    $distinctCitiCount = $stats['distinct_citi_count'] ?? 0;
    $distinctIndustryCount = $stats['distinct_industry_count'] ?? 0;
}
    // 输出 $dayQgskdt
  ?>
