<?php
    // 3. 按顺序遍历每个行业（带索引，用于关联颜色）
    foreach ($industrie as $index => $industry) {
        // 计算当前行业对应的颜色索引（核心：取余实现循环）
        if ($colourCount > 0) {
            $colourIndex = $index % $colourCount; // 索引取余，如：行业0→0，行业1→1，行业2→0（颜色数量为2时）
            $currentColour = $colours[$colourIndex];
        } else {
            $currentColour = $defaultColour; // 无颜色数据时用默认色
        }

        // 4. 查询当前行业在主表中的所有授课记录
        $recordStmt = $pdo->prepare("
            SELECT name, lname, citi, subject, subject2, remarks
            FROM `全国授课动态`
            WHERE industry = :industry
        ");
        $recordStmt->bindParam(':industry', $industry, PDO::PARAM_STR);
        $recordStmt->execute();
        $records = $recordStmt->fetchAll();
        
        // 为每个行业创建独立的div区块（外层容器）
        echo '<div class="frame b0c4faae9af4">'; // 行业容器开始
        
        // 行业标题区域（使用当前颜色）
        echo '<div class="frame b0c4faaec758" style="background: ' . htmlspecialchars($currentColour) . ';">';
            echo '<div class="shape text b0c4faaec760">';
                echo '<div class="text-node-html" id="html-text-node-417d4309-eea0-804f-8006-b0c4faaec760" data-x="12102.999999999998" data-y="7514.832391496481">';
                    echo '<div class="root rich-text root-0" xmlns="http://www.w3.org/1999/xhtml">';
                        echo '<div class="paragraph-set root-0-paragraph-set-0">';
                            echo '<p class="paragraph root-0-paragraph-set-0-paragraph-0" dir="ltr">';
                                echo '<span class="text-node root-0-paragraph-set-0-paragraph-0-text-0" style="white-space: pre;">' . htmlspecialchars($industry) . '</span>';
                            echo '</p>'; // 闭合p
                        echo '</div>'; // 闭合paragraph-set
                    echo '</div>'; // 闭合root
                echo '</div>'; // 闭合text-node-html
            echo '</div>'; // 闭合shape.text
        echo '</div>'; // 闭合frame.b0c4faaec758（标题容器结束）
        
        // 遍历当前行业的授课记录
